function budgetStatus(p){if(!p||p<=0)return {label:'未設定',className:'unlimited'};if(p>=1)return{label:'已超出預算',className:'over'};if(p>=.8)return{label:'接近預算上限',className:'warn'};return{label:'預算內',className:'ok'};}
