 $('#budgetMonth').addEventListener('change',e=>{budgetMonth=e.target.value||today().slice(0,7);renderPlanner();});
 $('#budgetForm').addEventListener('submit',async e=>{e.preventDefault();const v=Number($('#budgetTotal').value)||0;if(!Number.isFinite(v)||v<0||v>=1e12){toast('總預算金額不正確');return;}const catsBudget={};for(const field of $$('[data-budget-cat]')){const amount=Number(field.value)||0;if(!Number.isFinite(amount)||amount<0||amount>=1e12){toast('分類預算金額不正確');return;}if(amount>0)catsBudget[field.dataset.budgetCat]=amount;}planner.budgets[budgetMonth]={total:v,cats:catsBudget};await savePlanner();renderPlanner();toast(`${budgetMonth} 預算設定已儲存 ✓`);});
